use std::{fs::File,io::{BufWriter,Write}};
use wiparse_core::bus_decode::{synthesize_ddsss,DdsssSynthRequest,decode_ddsss,DdsssConfig,DdsssSequence,DdsssExtension};
fn main(){let trace=synthesize_ddsss(&DdsssSynthRequest{packets:vec![vec![0x03,0x00,0x03],vec![0x03,0x10,0x13],vec![0x03,0x55,0x56]],checksum_errors:vec![1],..Default::default()}).unwrap();let result=decode_ddsss(&trace,&DdsssConfig{sequence:DdsssSequence::SeqA,extension:DdsssExtension::Off,fop_hz:Some(128000.)});let path=std::env::args().nth(1).unwrap();let mut out=BufWriter::new(File::create(path).unwrap());writeln!(out,"TIME,CH1").unwrap();for(x,y)in trace.x.iter().zip(trace.y.iter()){writeln!(out,"{x:.15},{y:.15}").unwrap();}println!("points={} frames={} bytes={} bits={} chips={} errors={}",trace.x.len(),result.frames.len(),result.byte_spans.len(),result.bits.len(),result.chips.len(),result.frames.iter().filter(|f|f.has_error()).count());}
